cat > /workspace/project/builder.py <<'PYEOF'
"""Optional C accelerator built in scratch during replay.

The collector is fully implemented in Python; ``epic_fnv1a`` only accelerates
the FNV-1a/64 folding of certificate bytes.  Every failure path falls back to
the pure Python fold, so a missing compiler never changes observable results.
"""

import ctypes
import os
import subprocess
import sys
import tempfile
from pathlib import Path

_LIB = None
_TRIED = False


def _candidates():
    scratch = os.environ.get('TMPDIR') or ''
    roots = [scratch, tempfile.gettempdir(), '/tmp', os.getcwd()]
    seen = []
    for root in roots:
        if root and root not in seen:
            seen.append(root)
            try:
                if os.path.isdir(root) and os.access(root, os.W_OK):
                    yield root
            except OSError:
                pass


def _compile(source, output):
    for command in (['gcc', '-std=c11', '-O2', '-fPIC', '-shared',
                     '-o', output, str(source)],
                    ['cc', '-std=c11', '-O2', '-fPIC', '-shared',
                     '-o', output, str(source)]):
        try:
            done = subprocess.run(command, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE, timeout=90)
        except (OSError, subprocess.SubprocessError):
            continue
        if done.returncode == 0 and os.path.exists(output):
            return True
    return False


def accelerator():
    """Return a loaded library exposing epic_fnv1a, or None."""
    global _LIB, _TRIED
    if _TRIED:
        return _LIB
    _TRIED = True
    source = Path(__file__).resolve().parent / 'src' / 'epic_fold.c'
    try:
        if not source.is_file():
            return None
        for root in _candidates():
            try:
                build = tempfile.mkdtemp(prefix='epic-fold-', dir=root)
            except (OSError, tempfile.Error):
                continue
            output = os.path.join(build, 'libepicfold.so')
            try:
                if not _compile(source, output):
                    continue
                lib = ctypes.CDLL(output)
                lib.epic_fnv1a.argtypes = [ctypes.c_uint64, ctypes.c_char_p,
                                           ctypes.c_size_t]
                lib.epic_fnv1a.restype = ctypes.c_uint64
                probe = lib.epic_fnv1a(14695981039346656037, b'', 0)
                if probe != 14695981039346656037:
                    continue
                _LIB = lib
                return _LIB
            finally:
                try:
                    for name in os.listdir(build):
                        os.unlink(os.path.join(build, name))
                    os.rmdir(build)
                except OSError:
                    pass
    except Exception:
        _LIB = None
    return _LIB
PYEOF
